{thm:resistance-exponent}
For every classical EIGS hierarchical lattice, there is a deterministic $\lambda_{\mathfrak C}>1$ such that, almost surely,
\[
\lim_{n\to\infty}\frac{\log\mathscr{R}_{\mathfrak C_n}(\mathfrak v_+,\mathfrak v_-)}{n}
=\log\lambda_{\mathfrak C}.
\]

\label{def:critical-cluster}
As in \cite[Section~2.1]{NeroliIGSII2026}, let $\mathfrak C_n$ be the full terminal-connected cluster in $\Xi^n$, conditioned on crossing, including all dangling branches.
Its chemical distance $d_{\mathfrak C_n}$ is the intrinsic graph distance along open edges.

\label{lem:mass-perron}
Every fixed retained-component cylinder has a compatible limiting normalised vertex mass, with positive mass for connected cylinders.
The two sides of $b$ use their original joint law.

\label{thm:resistance-exponent}
There is a deterministic $\lambda_{\mathfrak C}>1$ such that
\[
 \lim_{n\to\infty}\frac{\log\mathscr{R}_{\mathfrak C_{n}}(\mathfrak v_+,\mathfrak v_-)}{n}
 =\lim_{n\to\infty}\frac{\mathbb E\log\mathscr{R}_{\mathfrak C_{n}}(\mathfrak v_+,\mathfrak v_-)}{n}
 =\lim_{n\to\infty}\frac{\log\mathbb E\mathscr{R}_{\mathfrak C_{n}}(\mathfrak v_+,\mathfrak v_-)}{n}
 =\log\lambda_{\mathfrak C},
\]
where the first limit holds almost surely.
The conclusions hold at every fixed connected address, and $\varphi_R'(p_c)\le\lambda_{\mathfrak C}\le \mathbb E|P(H)|$.

\label{lem:electrical-compactness}
The sequence $\bigl(\lambda_{\mathfrak C}^{-n}\mathscr{R}_{\mathfrak C_{n}}(\mathfrak v_+,\mathfrak v_-)\bigr)$ is relatively compact in the original $L^2$ space.
Its omega-limit set contains $cX_\varnothing$ for a deterministic $c\in[1,(\mathbb E X_\varnothing^{-1})]$.

\label{thm:electrical-amplitudes}
There is a deterministic $c_{\mathrm R}>0$ such that
$\displaystyle\lim_{n\to\infty}\lambda_{\mathfrak C}^{-n}\mathscr{R}_{\mathfrak C_{u,n}}(\mathfrak v_+,\mathfrak v_-)=c_{\mathrm R}X_u$ almost surely at every connected address and in every finite positive $L^p$.

\label{cor:electrical-moment-limits}
For every fixed $t\in\mathbb R$,
$\displaystyle\lim_{n\to\infty}\lambda_{\mathfrak C}^{-nt}\mathbb E\mathscr{R}_{\mathfrak C_{n}}(\mathfrak v_+,\mathfrak v_-)^t=c_{\mathrm R}^{\,t}\mathbb E X_\varnothing^t$.

\label{cor:deterministic-clock}
Under deterministic acceleration $(\rho(\mathbf M_{\mathfrak C})\lambda_{\mathfrak C})^n$, simple random walk converges conditionally to $(B_{t/(2v_cW_c)})_{t\ge0}$, equivalently to the resistance-form process with speed measure $2v_cW_c\mu$.
For the variable-speed walk, replace $2v_cW_c$ by $W_c$.

\label{thm:heat-kernels}\label{lem:spectral-typical}
Almost surely, for $\mu$-almost every $x\in \mathfrak C$,
\begin{equation}\label{eq:spectral-dimension-form}
 \dim_{\mathrm S}^{(\mathrm N)}(\mathfrak C:x)=\frac{2\log\rho(\mathbf M_{\mathfrak C})}{\log(\rho(\mathbf M_{\mathfrak C})\lambda_{\mathfrak C})}
 =\frac{2\dim_{\mathrm B}(\mathfrak C,d_{\mathrm{ch}})}{\dim_{\mathrm B}(\mathfrak C,d_{\mathrm{ch}})+\dim_{\mathrm R}(\mathfrak C,d_{\mathrm{ch}})}.
\end{equation}

\label{lem:strict-chemical-resistance}
For every classical rule,
$1<\lambda_{\mathfrak C}<\ell_{\mathfrak C}^{\mathrm{ch}}$.

\label{lem:chemical-compactness}
The eigenlaw has a stationary realisation measurable with respect to the original innovation tree.
There are deterministic finite $C,C'$ such that
\[
 \begin{gathered}
 1\le\mathbb E \bigl((\ell_{\mathfrak C}^{\mathrm{ch}})^{-n}d_{\mathfrak C_{n}}(\mathfrak v_+,\mathfrak v_-)\bigr)\le C,\qquad
 \sup_n\mathbb E e^{t\bigl((\ell_{\mathfrak C}^{\mathrm{ch}})^{-n}d_{\mathfrak C_{n}}(\mathfrak v_+,\mathfrak v_-)\bigr)}<\infty\ (t>0),\qquad
 \\
 X^{\mathrm{ch}}\le\liminf_n\bigl((\ell_{\mathfrak C}^{\mathrm{ch}})^{-n}d_{\mathfrak C_{n}}(\mathfrak v_+,\mathfrak v_-)\bigr)\le\limsup_n\bigl((\ell_{\mathfrak C}^{\mathrm{ch}})^{-n}d_{\mathfrak C_{n}}(\mathfrak v_+,\mathfrak v_-)\bigr)\le C'X^{\mathrm{ch}}
 \quad\text{almost surely}.
 \end{gathered}
\]
The sequence is relatively compact in this same $L^2$ probability space.

\label{lem:full-mesh}
For every live type, the supremum over all remaining depths of each $\ell_{\mathfrak C}^{\mathrm{ch}}$-normalised retained-component diameter has every finite positive moment.
Almost surely there are exponentially decreasing bounds $\Gamma_k$ with $\displaystyle\lim_{k\to\infty}\Gamma_k=0$ for all generation-$k$ intrinsic component diameters in $(\ell_{\mathfrak C}^{\mathrm{ch}})^{-n}d_{\mathfrak C_n}$, simultaneously for all $n\ge k$.

\label{lem:spectral-moments}
For each $\varepsilon>0$, almost surely,
\begin{equation}\label{eq:spectral-maxima}
 \max_{A\in\mathcal A_k}(Y_A+H_A)
 +\max_{\substack{|u|=k\\T_u=c}}X_u^{-1}
 \le C_{\omega,\varepsilon}e^{\varepsilon k}\qquad(k\ge0).
\end{equation}
An empty maximum is zero.

Each substitution multiplies the geometric socket degree at a planted vertex by $d_R$.
At most $2d_R^n$ descendant sockets contribute to the collar of one component.
For a side of $b$ its mass is bounded by the whole socket mass.
Conditional expected continuation masses are at most $\max_\sigma h_\sigma$, while $\mathbb E|\mathbf Z_k|\le C_0\rho(\mathbf M_{\mathfrak C})^k$.
Subadditivity gives
\begin{equation}\label{eq:collar-mass}
 \mathbb E[W_c\mu(C_{k,n})]\le C_1\rho(\mathbf M_{\mathfrak C})^kd_R^n\rho(\mathbf M_{\mathfrak C})^{-k-n}
 =C_1(d_R/\rho(\mathbf M_{\mathfrak C}))^n.
\end{equation}
This does not require independent $b$ sides or prior mass additivity at boundaries.

\label{lem:spectral-collars}
On one event of probability one, for $\mu$-almost every $x$, its unique generation-$k$ component $A_k(x)$ has $\mu(A_k(x))=\rho(\mathbf M_{\mathfrak C})^{-k}e^{o(k)}$.
For each positive rational $\eta$, such points lie outside $C_{k,\lceil\eta k\rceil}$ eventually.

\label{lem:resolvent-variational}
For $s>0$ and $x\in \mathfrak C$,
\begin{equation}\label{eq:resolvent-variational}
 G_s(x,x)=\sup_{f\in\mathcal D,\;f\ne0}
 \frac{f(x)^2}{\mathcal E(f)+s\|f\|_{L^2(\mu)}^2}.
\end{equation}

\label{lem:resolvent-component-bound}
For a positive-mass component $A$ containing $x$,
\begin{equation}\label{eq:resolvent-component}
 G_s(x,x)\le2\max\left\{\frac1{s\mu(A)},
               \operatorname{diam}^{\mathrm{intr}}_{R_*}(A)\right\}.
\end{equation}

\label{lem:spectral-resolvent}
For $0<\beta<1$, a resolvent asymptotic $G_s(x,x)=s^{\beta-1+o(1)}$ implies $p_t(x,x)=t^{-\beta+o(1)}$.
Two-sided constant-factor resolvent bounds imply the corresponding constant-factor heat-kernel bounds.
